@Test
public void testSuccessfulStateTransitionInvokesListener() {
    final TestConfiguredObject parent = new TestConfiguredObject("parent");
    parent.create();
    final AtomicReference<State> newState = new AtomicReference<>();
    final AtomicInteger callCounter = new AtomicInteger();
    parent.addChangeListener(new AbstractConfigurationChangeListener() {

        @Override
        public void stateChanged(final ConfiguredObject<?> object, final State old, final State state) {
            super.stateChanged(object, old, state);
            callCounter.incrementAndGet();
            newState.set(state);
        }
    });
    parent.delete();
    assertEquals(State.DELETED, newState.get());
    assertEquals(1, (long) callCounter.get());
}

@Test
public void testSuccessfulDeletion() {
    final TestConfiguredObject configuredObject = new TestConfiguredObject("configuredObject");
    configuredObject.create();
    final List<ChangeEvent> events = new ArrayList<>();
    configuredObject.addChangeListener(new AbstractConfigurationChangeListener() {

        @Override
        public void attributeSet(ConfiguredObject<?> object, String attributeName, Object oldAttributeValue, Object newAttributeValue) {
            events.add(new ChangeEvent(EventType.ATTRIBUTE_SET, object, attributeName, oldAttributeValue, newAttributeValue));
        }

        @Override
        public void stateChanged(ConfiguredObject<?> object, State oldState, State newState) {
            events.add(new ChangeEvent(EventType.STATE_CHANGED, object, ConfiguredObject.DESIRED_STATE, oldState, newState));
        }
    });
    configuredObject.delete();
    assertEquals(2, (long) events.size());
    assertEquals(State.DELETED, configuredObject.getDesiredState());
    assertEquals(State.DELETED, configuredObject.getState());
    assertEquals(2, (long) events.size(), "Unexpected events number");
    final ChangeEvent event0 = events.get(0);
    final ChangeEvent event1 = events.get(1);
    assertEquals(new ChangeEvent(EventType.STATE_CHANGED, configuredObject, Exchange.DESIRED_STATE, State.ACTIVE, State.DELETED), event0, "Unexpected first event: " + event0);
    assertEquals(new ChangeEvent(EventType.ATTRIBUTE_SET, configuredObject, Exchange.DESIRED_STATE, State.ACTIVE, State.DELETED), event1, "Unexpected second event: " + event1);
}

@Test
public void testAttributePersistence() {
    final String objectName = "testNonPersistAttributes";
    final TestSingleton object = _objectFactory.create(TestSingleton.class, Map.of(ConfiguredObject.NAME, objectName), null);
    assertEquals(objectName, object.getName());
    assertNull(object.getAutomatedNonPersistedValue());
    assertNull(object.getAutomatedPersistedValue());
    assertEquals(TestSingletonImpl.DERIVED_VALUE, object.getDerivedValue());
    ConfiguredObjectRecord record = object.asObjectRecord();
    assertEquals(objectName, record.getAttributes().get(ConfiguredObject.NAME));
    assertFalse(record.getAttributes().containsKey(TestSingleton.AUTOMATED_PERSISTED_VALUE));
    assertFalse(record.getAttributes().containsKey(TestSingleton.AUTOMATED_NONPERSISTED_VALUE));
    assertFalse(record.getAttributes().containsKey(TestSingleton.DERIVED_VALUE));
    final String newValue = "newValue";
    final Map<String, Object> updatedAttributes = Map.of(TestSingleton.AUTOMATED_PERSISTED_VALUE, newValue, TestSingleton.AUTOMATED_NONPERSISTED_VALUE, newValue, TestSingleton.DERIVED_VALUE, // Will be ignored
    System.currentTimeMillis());
    object.setAttributes(updatedAttributes);
    assertEquals(newValue, object.getAutomatedPersistedValue());
    assertEquals(newValue, object.getAutomatedNonPersistedValue());
    record = object.asObjectRecord();
    assertEquals(objectName, record.getAttributes().get(ConfiguredObject.NAME));
    assertEquals(newValue, record.getAttributes().get(TestSingleton.AUTOMATED_PERSISTED_VALUE));
    assertFalse(record.getAttributes().containsKey(TestSingleton.AUTOMATED_NONPERSISTED_VALUE));
    assertFalse(record.getAttributes().containsKey(TestSingleton.DERIVED_VALUE));
}

