@Test
public void testGetVisiblePreferences() {
    final String testGroupName = "testGroup";
    Subject sharer = TestPrincipalUtils.createTestSubject(TEST_USERNAME2, testGroupName);
    Subject nonSharer = TestPrincipalUtils.createTestSubject(TEST_USERNAME, testGroupName);
    final Preference sharedPreference = PreferenceFactory.fromAttributes(_testObject, PreferenceTestHelper.createPreferenceAttributes(null, null, "X-testType", "propName1", "shared with group", TEST_PRINCIPAL2_SERIALIZATION, Set.of(TestPrincipalUtils.getTestPrincipalSerialization(testGroupName)), Map.of()));
    final Preference notSharedPreference = PreferenceFactory.fromAttributes(_testObject, PreferenceTestHelper.createPreferenceAttributes(null, null, "X-testType", "propName2", null, TEST_PRINCIPAL2_SERIALIZATION, null, Map.of()));
    updateOrAppendAs(sharer, sharedPreference, notSharedPreference);
    final Preference nonSharersPrivatePref = PreferenceFactory.fromAttributes(_testObject, PreferenceTestHelper.createPreferenceAttributes(null, null, "X-testType", "propName", null, TEST_PRINCIPAL_SERIALIZATION, null, Map.of()));
    updateOrAppendAs(nonSharer, nonSharersPrivatePref);
    Subject.doAs(nonSharer, (PrivilegedAction<Void>) () -> {
        Set<Preference> retrievedPreferences = awaitPreferenceFuture(_testObject.getUserPreferences().getVisiblePreferences());
        assertEquals(2, (long) retrievedPreferences.size(), "Unexpected number of preferences");
        Set<UUID> visibleIds = new HashSet<>(retrievedPreferences.size());
        for (Preference preference : retrievedPreferences) {
            visibleIds.add(preference.getId());
        }
        assertTrue(visibleIds.contains(nonSharersPrivatePref.getId()), "Owned preference not visible");
        assertTrue(visibleIds.contains(sharedPreference.getId()), "Shared preference not visible");
        return null;
    });
}

