@Test
public void testMaximumMessageTtl() {
    // Test scenarios where only the maximum TTL has been set
    Map<String, Object> attributes = ImmutableMap.<String, Object>builder().putAll(_arguments).put(Queue.NAME, "testTtlOverrideMaximumTTl").put(Queue.MAXIMUM_MESSAGE_TTL, 10000L).build();
    Queue<?> queue = _virtualHost.createChild(Queue.class, attributes);
    assertEquals(60000L, getExpirationOnQueue(queue, 50000L, 0L), "TTL has not been overridden");
    assertEquals(60000L, getExpirationOnQueue(queue, 50000L, 65000L), "TTL has not been overridden");
    assertEquals(55000L, getExpirationOnQueue(queue, 50000L, 55000L), "TTL has been incorrectly overridden");
    final long tooLateExpiration = System.currentTimeMillis() + 20000L;
    assertTrue(tooLateExpiration != getExpirationOnQueue(queue, 0L, tooLateExpiration), "TTL has not been overridden");
    long acceptableExpiration = System.currentTimeMillis() + 5000L;
    assertEquals(acceptableExpiration, getExpirationOnQueue(queue, 0L, acceptableExpiration), "TTL has been incorrectly overriden");
    // Test the scenarios where only the minimum TTL has been set
    attributes = ImmutableMap.<String, Object>builder().putAll(_arguments).put(Queue.NAME, "testTtlOverrideMinimumTTl").put(Queue.MINIMUM_MESSAGE_TTL, 10000L).build();
    queue = _virtualHost.createChild(Queue.class, attributes);
    assertEquals(0L, getExpirationOnQueue(queue, 50000L, 0L), "TTL has been overridden incorrectly");
    assertEquals(65000L, getExpirationOnQueue(queue, 50000L, 65000L), "TTL has been overridden incorrectly");
    assertEquals(60000L, getExpirationOnQueue(queue, 50000L, 55000L), "TTL has not been overriden");
    final long unacceptableExpiration = System.currentTimeMillis() + 5000L;
    assertTrue(unacceptableExpiration != getExpirationOnQueue(queue, 0L, tooLateExpiration), "TTL has not been overridden");
    acceptableExpiration = System.currentTimeMillis() + 20000L;
    assertEquals(acceptableExpiration, getExpirationOnQueue(queue, 0L, acceptableExpiration), "TTL has been incorrectly overridden");
    // Test the scenarios where both the minimum and maximum TTL have been set
    attributes = ImmutableMap.<String, Object>builder().putAll(_arguments).put(Queue.NAME, "testTtlOverrideBothTTl").put(Queue.MINIMUM_MESSAGE_TTL, 10000L).put(Queue.MAXIMUM_MESSAGE_TTL, 20000L).build();
    queue = _virtualHost.createChild(Queue.class, attributes);
    assertEquals(70000L, getExpirationOnQueue(queue, 50000L, 0L), "TTL has not been overridden");
    assertEquals(65000L, getExpirationOnQueue(queue, 50000L, 65000L), "TTL has been overridden incorrectly");
    assertEquals(60000L, getExpirationOnQueue(queue, 50000L, 55000L), "TTL has not been overridden");
}

