        messageId++;
        _sqel.add(msg, null);
    }
    final QueueEntryIterator iter = getTestList().iterator();
    int count = 0;
    while (iter.advance()) {
        assertEquals(TEXTKEYS[count], getSortedKeyValue(iter), "Sorted queue entry value is not as expected");
