@Test
public void testAddChildAndThenDelete() throws ExecutionException, InterruptedException {
    // No children should be present before the test starts
    assertEquals(0, _authManager.getChildren(User.class).size(), "No users should be present before the test starts");
    assertEquals(0, _authManager.getUsers().size(), "No users should be present before the test starts");
    final Map<String, Object> childAttrs = new HashMap<>();
    childAttrs.put(User.NAME, getTestName());
    childAttrs.put(User.PASSWORD, "password");
    final User<?> user = _authManager.addChildAsync(User.class, childAttrs).get();
    assertNotNull(user, "User should be created but addChild returned null");
    assertEquals(getTestName(), user.getName());
    if (!isPlain()) {
        // password shouldn't actually be the given string, but instead hashed value
        assertNotEquals("password", user.getPassword(), "Password shouldn't actually be the given string, but instead hashed value");
    }
    AuthenticationResult authResult = _authManager.authenticate(getTestName(), "password");
    assertEquals(AuthenticationResult.AuthenticationStatus.SUCCESS, authResult.getStatus(), "User should authenticate with given password");
    assertEquals(1, _authManager.getChildren(User.class).size(), "Manager should have exactly one user child");
    assertEquals(1, _authManager.getUsers().size(), "Manager should have exactly one user child");
    user.delete();
    assertEquals(0, _authManager.getChildren(User.class).size(), "No users should be present after child deletion");
    authResult = _authManager.authenticate(getTestName(), "password");
    assertEquals(AuthenticationResult.AuthenticationStatus.ERROR, authResult.getStatus(), "User should no longer authenticate with given password");
}

@Test
public void testCreateUser() {
    assertEquals(0, _authManager.getChildren(User.class).size(), "No users should be present before the test starts");
    assertTrue(_authManager.createUser(getTestName(), "password", Map.of()));
    assertEquals(1, _authManager.getChildren(User.class).size(), "Manager should have exactly one user child");
    final User<?> user = _authManager.getChildren(User.class).iterator().next();
    assertEquals(getTestName(), user.getName());
    if (!isPlain()) {
        // password shouldn't actually be the given string, but instead salt and the hashed value
        assertNotEquals("password", user.getPassword(), "Password shouldn't actually be the given string, but instead salt and the hashed value");
    }
    final Map<String, Object> childAttrs = Map.of(User.NAME, getTestName(), User.PASSWORD, "password");
    assertThrows(IllegalArgumentException.class, () -> _authManager.addChildAsync(User.class, childAttrs).get(), "Should not be able to create a second user with the same name");
    assertDoesNotThrow(() -> _authManager.deleteUser(getTestName()), "AccountNotFoundException thrown when none was expected");
    assertThrows(AccountNotFoundException.class, () -> _authManager.deleteUser(getTestName()), "AccountNotFoundException not thrown when none was expected");
}

@Test
public void testUpdateUser() {
    assertTrue(_authManager.createUser(getTestName(), "password", Map.of()));
    assertTrue(_authManager.createUser(getTestName() + "_2", "password", Map.of()));
    assertEquals(2, _authManager.getChildren(User.class).size(), "Manager should have exactly two user children");
    AuthenticationResult authResult = _authManager.authenticate(getTestName(), "password");
    assertEquals(AuthenticationResult.AuthenticationStatus.SUCCESS, authResult.getStatus(), "User should authenticate with given password");
    authResult = _authManager.authenticate(getTestName() + "_2", "password");
    assertEquals(AuthenticationResult.AuthenticationStatus.SUCCESS, authResult.getStatus(), "User should authenticate with given password");
    for (final User<?> user : _authManager.getChildren(User.class)) {
        if (user.getName().equals(getTestName())) {
            user.setAttributes(Map.of(User.PASSWORD, "newpassword"));
        }
    }
    authResult = _authManager.authenticate(getTestName(), "newpassword");
    assertEquals(AuthenticationResult.AuthenticationStatus.SUCCESS, authResult.getStatus(), "User should authenticate with updated password");
    authResult = _authManager.authenticate(getTestName() + "_2", "password");
    assertEquals(AuthenticationResult.AuthenticationStatus.SUCCESS, authResult.getStatus(), "User should authenticate with original password");
    authResult = _authManager.authenticate(getTestName(), "password");
    assertEquals(AuthenticationResult.AuthenticationStatus.ERROR, authResult.getStatus(), "User not authenticate with original password");
    for (final User<?> user : _authManager.getChildren(User.class)) {
        if (user.getName().equals(getTestName())) {
            user.setPassword("newerpassword");
        }
    }
    authResult = _authManager.authenticate(getTestName(), "newerpassword");
    assertEquals(AuthenticationResult.AuthenticationStatus.SUCCESS, authResult.getStatus(), "User should authenticate with updated password");
}

