@Test
public void testCreationFailsOnInvalidSecret() throws Exception {
    IllegalArgumentException thrown = assertThrows(IllegalArgumentException.class, () -> new AESGCMKeyFileEncrypter(null), "An encrypter should not be creatable from a null key");
    assertTrue(thrown.getMessage().contains("A non null secret key must be supplied"), "Unexpected exception message:" + thrown.getMessage());
    final PBEKeySpec keySpec = new PBEKeySpec(SECRET.toCharArray());
    final SecretKeyFactory factory = SecretKeyFactory.getInstance("PBEWithMD5AndDES");
    thrown = assertThrows(IllegalArgumentException.class, () -> new AESGCMKeyFileEncrypter(factory.generateSecret(keySpec)), "An encrypter should not be creatable from the wrong type of secret key");
    assertTrue(thrown.getMessage().contains("Provided secret key was for the algorithm: PBEWithMD5AndDES when AES was needed."), "Unexpected exception message:" + thrown.getMessage());
}

