@Test
public void testUpdateTrustStore_Success() throws Exception {
    final StoreAndCrl<Path> data = generateTrustStoreAndCrl();
    final Map<String, Object> attributes = Map.of(FileTrustStore.NAME, NAME, FileTrustStore.STORE_URL, data.getStore().toFile().getAbsolutePath(), FileTrustStore.PASSWORD, TLS_RESOURCE.getSecret(), FileTrustStore.TRUST_STORE_TYPE, TLS_RESOURCE.getKeyStoreType(), FileTrustStore.CERTIFICATE_REVOCATION_CHECK_ENABLED, true, FileTrustStore.CERTIFICATE_REVOCATION_LIST_URL, data.getCrl().toFile().getAbsolutePath());
    final FileTrustStore<?> fileTrustStore = createFileTrustStore(attributes);
    assertEquals(data.getStore().toFile().getAbsolutePath(), fileTrustStore.getStoreUrl(), "Unexpected path value before change");
    IllegalConfigurationException thrown = assertThrows(IllegalConfigurationException.class, () -> fileTrustStore.setAttributes(Map.of(FileTrustStore.STORE_URL, NOT_A_TRUSTSTORE)), "Exception not thrown");
    assertTrue(thrown.getMessage().contains("Cannot instantiate trust store"), "Exception text not as unexpected:" + thrown.getMessage());
    assertEquals(data.getStore().toFile().getAbsolutePath(), fileTrustStore.getStoreUrl(), "Unexpected keystore path value after failed change");
    thrown = assertThrows(IllegalConfigurationException.class, () -> fileTrustStore.setAttributes(Map.of(FileTrustStore.CERTIFICATE_REVOCATION_LIST_URL, NOT_A_CRL)), "Exception not thrown");
    assertTrue(thrown.getMessage().contains(String.format("Unable to load certificate revocation list '%s' for truststore '%s'", NOT_A_CRL, NAME)), "Exception text not as unexpected:" + thrown.getMessage());
    assertEquals(data.getCrl().toFile().getAbsolutePath(), fileTrustStore.getCertificateRevocationListUrl(), "Unexpected CRL path value after failed change");
    assertEquals(data.getStore().toFile().getAbsolutePath(), fileTrustStore.getStoreUrl(), "Unexpected path value after failed change");
    final Path keyStoreFile2 = TLS_RESOURCE.createTrustStore(DN_FOO, data.getCa());
    final Path emptyCrl = TLS_RESOURCE.createCrl(data.getCa());
    final Map<String, Object> changedAttributes = Map.of(FileTrustStore.STORE_URL, keyStoreFile2.toFile().getAbsolutePath(), FileTrustStore.PASSWORD, TLS_RESOURCE.getSecret(), FileTrustStore.CERTIFICATE_REVOCATION_LIST_URL, emptyCrl.toFile().getAbsolutePath());
    fileTrustStore.setAttributes(changedAttributes);
    assertEquals(keyStoreFile2.toFile().getAbsolutePath(), fileTrustStore.getStoreUrl(), "Unexpected keystore path value after change that is expected to be successful");
    assertEquals(emptyCrl.toFile().getAbsolutePath(), fileTrustStore.getCertificateRevocationListUrl(), "Unexpected CRL path value after change that is expected to be successful");
}

