@Test
public void testDeregister_BlockedUser() {
    final CachedLimiter limiter = ConnectionLimiter.blockEveryone();
    final AMQPConnection<?> connection = newConnection();
    final ConnectionLimitException thrown = assertThrows(ConnectionLimitException.class, () -> limiter.register(connection), "A connection limit exception is expected");
    assertNotNull(thrown.getMessage());
    for (int i = 0; i < 7; i++) {
