@Test
public void generateSelfSignedCertificate() throws Exception {
    final String keyAlgorithm = "RSA";
    final String signatureAlgorithm = "SHA256withRSA";
    final int keyLength = 2048;
    final Set<InetAddress> addresses = Collections.list(NetworkInterface.getNetworkInterfaces()).stream().flatMap(networkInterface -> networkInterface.getInterfaceAddresses().stream()).map(InterfaceAddress::getAddress).collect(Collectors.toSet());
    final Set<String> dnsNames = addresses.stream().map(address -> address.getHostName() != null ? address.getHostName() : address.getCanonicalHostName()).filter(Objects::nonNull).collect(Collectors.toSet());
    final long startTime = System.currentTimeMillis();
    final long endTime = Instant.ofEpochMilli(startTime).plus(365, ChronoUnit.DAYS).toEpochMilli();
    final SSLUtil.KeyCertPair keyCertPair = SSLUtil.generateSelfSignedCertificate(keyAlgorithm, signatureAlgorithm, keyLength, startTime, endTime, "CN=Qpid", dnsNames, addresses);
    assertNotNull(keyCertPair);
    assertNotNull(keyCertPair.getCertificate());
    assertNotNull(keyCertPair.getPrivateKey());
    assertEquals(keyAlgorithm, keyCertPair.getPrivateKey().getAlgorithm());
    assertTrue(signatureAlgorithm.equalsIgnoreCase(keyCertPair.getCertificate().getSigAlgName()));
}

