@Test
void userRuleParsing() {
    final AclRulePredicates predicates = new AclRulePredicatesBuilder().put(Property.NAME, "otherUser").build();
    validateRule(writeACLConfig("ACL ALLOW user1 CREATE USER"), "user1", LegacyOperation.CREATE, ObjectType.USER, EMPTY);
    validateRule(writeACLConfig("ACL ALLOW user1 CREATE USER name=\"otherUser\""), "user1", LegacyOperation.CREATE, ObjectType.USER, predicates);
    validateRule(writeACLConfig("ACL ALLOW user1 DELETE USER"), "user1", LegacyOperation.DELETE, ObjectType.USER, EMPTY);
    validateRule(writeACLConfig("ACL ALLOW user1 DELETE USER name=\"otherUser\""), "user1", LegacyOperation.DELETE, ObjectType.USER, predicates);
    validateRule(writeACLConfig("ACL ALLOW user1 UPDATE USER"), "user1", LegacyOperation.UPDATE, ObjectType.USER, EMPTY);
    validateRule(writeACLConfig("ACL ALLOW user1 UPDATE USER name=\"otherUser\""), "user1", LegacyOperation.UPDATE, ObjectType.USER, predicates);
    validateRule(writeACLConfig("ACL ALLOW user1 ALL USER"), "user1", LegacyOperation.ALL, ObjectType.USER, EMPTY);
    validateRule(writeACLConfig("ACL ALLOW user1 ALL USER name=\"otherUser\""), "user1", LegacyOperation.ALL, ObjectType.USER, predicates);
}

@Test
void groupRuleParsing() {
    final AclRulePredicates predicates = new AclRulePredicatesBuilder().put(Property.NAME, "groupName").build();
    validateRule(writeACLConfig("ACL ALLOW user1 CREATE GROUP"), "user1", LegacyOperation.CREATE, ObjectType.GROUP, EMPTY);
    validateRule(writeACLConfig("ACL ALLOW user1 CREATE GROUP name=\"groupName\""), "user1", LegacyOperation.CREATE, ObjectType.GROUP, predicates);
    validateRule(writeACLConfig("ACL ALLOW user1 DELETE GROUP"), "user1", LegacyOperation.DELETE, ObjectType.GROUP, EMPTY);
    validateRule(writeACLConfig("ACL ALLOW user1 DELETE GROUP name=\"groupName\""), "user1", LegacyOperation.DELETE, ObjectType.GROUP, predicates);
