    object = new ObjectProperties("rs.broadcast");
    object.put(Property.ROUTING_KEY, "rs.broadcast.public");
    assertEquals(Result.DEFER, ruleSet.check(testSubject, LegacyOperation.PUBLISH, ObjectType.EXCHANGE, object));
}

