@Test
void notEquals() {
    final String identity = "identity";
    final RuleOutcome allow = RuleOutcome.ALLOW;
    final Rule rule = new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build();
    assertNotEquals(rule, new Rule.Builder().withIdentity("identity2").withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), "Different identity should cause rules to be unequal");
    assertNotEquals(new Rule.Builder().withIdentity("identity2").withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), rule, "Different identity should cause rules to be unequal");
    assertNotEquals(rule, new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.ACCESS).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), "Different operation should cause rules to be unequal");
    assertNotEquals(new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.ACCESS).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), rule, "Different action should cause rules to be unequal");
    assertNotEquals(rule, new Rule.Builder().withIdentity("identity2").withOperation(LegacyOperation.UPDATE).withObject(ObjectType.EXCHANGE).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), "Different object type should cause rules to be unequal");
    assertNotEquals(new Rule.Builder().withIdentity("identity2").withOperation(LegacyOperation.UPDATE).withObject(ObjectType.EXCHANGE).withOutcome(allow).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), rule, "Different object type should cause rules to be unequal");
    assertNotEquals(rule, new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(RuleOutcome.DENY).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), "Different permission should cause rules to be unequal");
    assertNotEquals(new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(RuleOutcome.DENY).withPredicate(Property.VIRTUALHOST_NAME, "vhname").build(), rule, "Different permission should cause rules to be unequal");
    assertNotEquals(rule, new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).build(), "Different predicates should cause rules to be unequal");
    assertNotEquals(new Rule.Builder().withIdentity(identity).withOperation(LegacyOperation.UPDATE).withObject(ObjectType.VIRTUALHOST).withOutcome(allow).build(), rule, "Different predicates should cause rules to be unequal");
    assertNotEquals(null, rule);
    assertNotEquals("rule", rule);
}

