    final File aclFile = new File(TMP_FOLDER, "my-non-existing-acl-" + System.currentTimeMillis());
    assertFalse(aclFile.exists(), "ACL file " + aclFile.getAbsolutePath() + " actually exists but should not");
    final Map<String, Object> attributes = Map.of(AccessControlProvider.ID, UUID.randomUUID(), AccessControlProvider.NAME, "acl", AccessControlProvider.TYPE, AclFileAccessControlProvider.ACL_FILE_PROVIDER_TYPE, AclFileAccessControlProvider.PATH, aclFile.getAbsolutePath());
    final IllegalConfigurationException thrown = assertThrows(IllegalConfigurationException.class, () -> _objectFactory.create(AccessControlProvider.class, attributes, _broker), "It should not be possible to create and initialise ACL with non existing file");
    assertTrue(Pattern.matches("Cannot convert .* to a readable resource", thrown.getMessage()), "Unexpected exception message: " + thrown.getMessage());
}

@Test
void validationOnCreateWithNonExistingACLFile() {
    final Map<String, Object> attributes = new HashMap<>();
    final String aclFilePath = new File(TMP_FOLDER, "test_" + getTestName() + System.nanoTime() + ".acl").getAbsolutePath();
    attributes.put("path", aclFilePath);
    attributes.put(AclFileAccessControlProvider.NAME, getTestName());
    final AclFileAccessControlProviderImpl aclProvider = new AclFileAccessControlProviderImpl(attributes, _broker);
    final IllegalConfigurationException thrown = assertThrows(IllegalConfigurationException.class, aclProvider::create, "Exception is expected on validation with non-existing ACL file");
    assertEquals(String.format("Cannot convert %s to a readable resource", aclFilePath), thrown.getMessage(), "Unexpected exception message:" + thrown.getMessage());
}

