    slot2.free();
    assertFalse(_registry.isRegistered(connection2));
    assertTrue(_registry.hasBeenRegistered(connection2));
    slot1.free();
    assertFalse(_registry.isRegistered(connection1));
    assertTrue(_registry.hasBeenRegistered(connection1));
}

