    "(select count(*) " + "from queue " + "where name not in (select name from important_queues) " + "or maximumQueueDepthMessages = -1 or maximumQueueDepthBytes = -1 " + "or overflowPolicy = 'RING' " + "and (queueDepthMessages < maximumQueueDepthMessages * 0.6 " + "or queueDepthBytes < maximumQueueDepthBytes * 0.6)) as goodQueuesCount, " + // bad queues have depth > 60% and < 90%
    "(select count(*) " + "from queue " + "where name in (select name from important_queues) " + "and maximumQueueDepthMessages != -1 and maximumQueueDepthBytes != -1 " + "and overflowPolicy != 'RING' " + "and (queueDepthMessages between (maximumQueueDepthMessages * 0.6, maximumQueueDepthMessages * 0.9) " + "or queueDepthBytes between (maximumQueueDepthBytes * 0.6, maximumQueueDepthBytes * 0.9))) as badQueuesCount, " + // critical queues have depth > 90%
    "(select count(*) " + "from queue " + "where name in (select name from important_queues) " + "and maximumQueueDepthMessages != -1 and maximumQueueDepthBytes != -1 " + "and overflowPolicy != 'RING' " + "and (queueDepthMessages > maximumQueueDepthMessages * 0.9 " + "or queueDepthBytes > maximumQueueDepthBytes * 0.9)) as criticalQueuesCount " + "from broker";
    List<Map<String, Object>> result = _queryEvaluator.execute(query).getResults();
    assertEquals(1, result.size());
    assertEquals("mock", result.get(0).get("label"));
    assertEquals(6_000_000_000L, result.get(0).get("heapMemoryUsage"));
    assertEquals(10_000_000_000L, result.get(0).get("maximumHeapMemorySize"));
    assertEquals(500_000_000L, result.get(0).get("directMemoryUsage"));
    assertEquals(1_500_000_000L, result.get(0).get("maximumDirectMemorySize"));
    assertEquals(5.2, result.get(0).get("cpuUsage"));
    assertEquals(10, result.get(0).get("certificatesCount"));
    assertEquals(30, result.get(0).get("connectionCount"));
    assertEquals(10, result.get(0).get("exchangesCount"));
    assertEquals(10, result.get(0).get("bindingsCount"));
    assertEquals(70, result.get(0).get("queuesCount"));
    assertEquals(0, result.get(0).get("usersCount"));
    assertEquals(65, result.get(0).get("goodQueuesCount"));
    assertEquals(3, result.get(0).get("badQueuesCount"));
    assertEquals(2, result.get(0).get("criticalQueuesCount"));
