@Test()
@SuppressWarnings("unchecked")
public void caseExpression() {
    String query = "select case when 1 > 2 then 1 else 2 end";
    List<Map<String, Object>> result = _queryEvaluator.execute(query).getResults();
    assertEquals("case when 1>2 then 1 else 2 end", result.get(0).keySet().iterator().next());
    query = "select (case when 1 > 2 then 1 else 2 end)";
    result = _queryEvaluator.execute(query).getResults();
    assertEquals("(case when 1>2 then 1 else 2 end)", result.get(0).keySet().iterator().next());
    query = "select " + "case " + "when (maximumQueueDepthMessages = -1 and maximumQueueDepthBytes = -1) or queueDepthMessages < maximumQueueDepthMessages * 0.6 then 'good' " + "when queueDepthMessages < maximumQueueDepthMessages * 0.9 then 'bad' " + "else 'critical' " + "end " + "from queue";
    result = _queryEvaluator.execute(query).getResults();
    assertEquals("case " + "when (maximumQueueDepthMessages=-1 and maximumQueueDepthBytes=-1) or queueDepthMessages<maximumQueueDepthMessages*0.6 then 'good' " + "when queueDepthMessages<maximumQueueDepthMessages*0.9 then 'bad' " + "else 'critical' " + "end", result.get(0).keySet().iterator().next());
    query = "select " + "case " + "when (maximumQueueDepthMessages = -1 and maximumQueueDepthBytes = -1) or queueDepthMessages < maximumQueueDepthMessages * 0.6 then 'good' " + "when queueDepthMessages < maximumQueueDepthMessages * 0.9 then 'bad' " + "else 'critical' " + "end, " + "count(*) " + "from queue group by 1";
    result = _queryEvaluator.execute(query).getResults();
    assertEquals("bad", ((Map<String, Object>) result.get(0).get("count(*)")).keySet().stream().skip(0).findFirst().orElse(null));
    assertEquals("critical", ((Map<String, Object>) result.get(0).get("count(*)")).keySet().stream().skip(1).findFirst().orElse(null));
    assertEquals("good", ((Map<String, Object>) result.get(0).get("count(*)")).keySet().stream().skip(2).findFirst().orElse(null));
}

