@Test()
public void customizeZoneIdViaQuerySettings() {
    final List<ZoneId> zoneIds = List.of(ZoneId.of("UTC"), ZoneId.of("GMT+1"), ZoneId.of("GMT+2"), ZoneId.of("GMT+3"), ZoneId.of("GMT+4"), ZoneId.of("GMT+5"), ZoneId.of("GMT+6"), ZoneId.of("GMT+7"), ZoneId.of("GMT+8"), ZoneId.of("GMT+9"), ZoneId.of("GMT+10"), ZoneId.of("GMT+11"), ZoneId.of("GMT+12"));
    zoneIds.forEach(zoneId -> {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendPattern(DefaultQuerySettings.DATE_TIME_PATTERN).appendFraction(ChronoField.NANO_OF_SECOND, 0, 6, true).toFormatter().withZone(zoneId);
        QueryEvaluator queryEvaluator = new QueryEvaluator(_broker);
        QuerySettings querySettings = new QuerySettingsBuilder().zoneId(zoneId).build();
        String query = "select current_timestamp() as result";
