@Test
public void messagingOnAbruptConnectivityLostWhilstConsuming() throws Exception {
    int minimumNumberOfMessagesToProduce = 40;
    int minimumNumberOfMessagesToConsume = 20;
    // produce minimum required number of messages before starting consumption
    final CountDownLatch queueDataWaiter = new CountDownLatch(1);
    final Producer producer = new Producer(_utilityConnection, _testQueue, Session.SESSION_TRANSACTED, minimumNumberOfMessagesToProduce, queueDataWaiter::countDown);
    // create tunneled connection to consume messages
    final ClientMonitor clientMonitor = new ClientMonitor();
    _tunneledConnection = createTunneledConnection(clientMonitor);
    _tunneledConnection.start();
    // consumer will consume minimum number of messages before abrupt disconnect
    Consumer consumer = new Consumer(_tunneledConnection, _testQueue, Session.SESSION_TRANSACTED, minimumNumberOfMessagesToConsume, () -> {
        try {
            _tcpTunneler.disconnect(clientMonitor.getClientAddress());
        } finally {
            producer.stop();
        }
    });
    LOGGER.debug("Waiting for producer to produce {} messages before consuming", minimumNumberOfMessagesToProduce);
    _executorService.submit(producer);
    assertTrue(queueDataWaiter.await(10, TimeUnit.SECONDS), "Latch waiting for produced messages was not count down");
    LOGGER.debug("Producer sent {} messages. Starting consumption...", producer.getNumberOfPublished());
    _executorService.submit(consumer);
    boolean disconnectOccurred = clientMonitor.awaitDisconnect(10, TimeUnit.SECONDS);
    LOGGER.debug("Stopping consumer and producer");
    consumer.stop();
    producer.stop();
    LOGGER.debug("Producer sent {} messages. Consumer received {} messages", producer.getNumberOfPublished(), consumer.getNumberOfConsumed());
    assertTrue(disconnectOccurred, "Client disconnect did not happen");
    assertTrue(producer.getNumberOfPublished() >= minimumNumberOfMessagesToProduce, "Unexpected number of published messages " + producer.getNumberOfPublished());
    assertTrue(consumer.getNumberOfConsumed() >= minimumNumberOfMessagesToConsume, "Unexpected number of consumed messages " + consumer.getNumberOfConsumed());
    LOGGER.debug("Remaining number to consume {}.", (producer.getNumberOfPublished() - consumer.getNumberOfConsumed()));
    consumeIgnoringLastSeenOmission(_utilityConnection, _testQueue, consumer.getNumberOfConsumed(), producer.getNumberOfPublished(), consumer.getLastSeenMessageIndex());
}

