        _producer.send(message);
        responseMessage = _consumer.receive(getReceiveTimeout());
        final Collection directExchanges = (Collection) getValueFromMapResponse(responseMessage, "results");
        assertTrue(directExchanges.size() < numberOfExchanges, "There are the same number of results when searching for direct exchanges as when searching for all exchanges");
        assertTrue(results.containsAll(directExchanges), "The list of direct exchanges is not a proper subset of the list of all exchanges");
    } finally {
        connection.close();
    }
