public void testParallelProductionAndConsumption() throws Exception {
    final String queueName = getTestName();
    final Queue queue = createConflationQueue(queueName, KEY_PROPERTY, false);
    int numberOfUniqueKeyValues = 2;
    final ExecutorService executorService = Executors.newFixedThreadPool(2);
    try {
        // Start producing threads that send messages
        final BackgroundMessageProducer messageProducer1 = new BackgroundMessageProducer(queue, numberOfUniqueKeyValues);
        final BackgroundMessageProducer messageProducer2 = new BackgroundMessageProducer(queue, numberOfUniqueKeyValues);
        final Future<?> future1 = executorService.submit(messageProducer1);
        final Future<?> future2 = executorService.submit(messageProducer2);
        final Map<String, Integer> lastReceivedMessages = receiveMessages(messageProducer1, queue);
        future1.get(getReceiveTimeout() * MSG_COUNT, TimeUnit.MILLISECONDS);
        future2.get(getReceiveTimeout() * MSG_COUNT, TimeUnit.MILLISECONDS);
        final Map<String, Integer> lastSentMessages1 = messageProducer1.getMessageSequenceNumbersByKey();
        assertEquals(numberOfUniqueKeyValues, lastSentMessages1.size(), "Unexpected number of last sent messages sent by producer1");
        final Map<String, Integer> lastSentMessages2 = messageProducer2.getMessageSequenceNumbersByKey();
        assertEquals(lastSentMessages1, lastSentMessages2);
        assertEquals(lastSentMessages1, lastReceivedMessages, "The last message sent for each key should match the last message received for that key");
        assertNull(messageProducer1.getException(), "Unexpected exception from background producer thread");
    } finally {
        executorService.shutdown();
    }
}

@Test
public void testPriority() throws Exception {
    final int priorities = 10;
    final Queue queue = createPriorityQueue(getTestName(), priorities);
    final Connection producerConnection = getConnection();
    try {
        final Session producerSession = producerConnection.createSession(true, Session.SESSION_TRANSACTED);
        final MessageProducer producer = producerSession.createProducer(queue);
        for (int msg = 0; msg < MSG_COUNT; msg++) {
            producer.setPriority(msg % priorities);
            producer.send(nextMessage(producerSession, msg));
        }
        producerSession.commit();
    } finally {
        producerConnection.close();
    }
    final Connection consumerConnection = getConnection();
    try {
        final Session consumerSession = consumerConnection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        final MessageConsumer consumer = consumerSession.createConsumer(queue);
        consumerConnection.start();
        Message previous = null;
        for (int messageCount = 0, expectedPriority = priorities - 1; messageCount < MSG_COUNT; messageCount++) {
            Message received = consumer.receive(getReceiveTimeout());
            assertNotNull(received, String.format("Message '%d' is not received", messageCount));
            assertEquals(expectedPriority, received.getJMSPriority(), String.format("Unexpected message '%d' priority", messageCount));
            if (previous != null) {
                assertTrue(previous.getJMSPriority() > received.getJMSPriority() || (previous.getJMSPriority() == received.getJMSPriority() && previous.getIntProperty("msg") < received.getIntProperty("msg")), String.format("Messages '%d' arrived in unexpected order : previous message '%d' priority is '%d', received message '%d' priority is '%d'", messageCount, previous.getIntProperty("msg"), previous.getJMSPriority(), received.getIntProperty("msg"), received.getJMSPriority()));
            }
            previous = received;
            if (messageCount > 0 && (messageCount + 1) % (MSG_COUNT / priorities) == 0) {
                expectedPriority--;
            }
        }
    } finally {
        consumerConnection.close();
    }
}

@Test
public void testOddOrdering() throws Exception {
    final Queue queue = createPriorityQueue(getTestName(), 3);
    final Connection producerConnection = getConnection();
    try {
        final Session producerSession = producerConnection.createSession(true, Session.SESSION_TRANSACTED);
        final MessageProducer producer = producerSession.createProducer(queue);
        // In order ABC
        producer.setPriority(9);
        producer.send(nextMessage(producerSession, 1));
        producer.setPriority(4);
        producer.send(nextMessage(producerSession, 2));
        producer.setPriority(1);
        producer.send(nextMessage(producerSession, 3));
        // Out of order BAC
        producer.setPriority(4);
        producer.send(nextMessage(producerSession, 4));
        producer.setPriority(9);
        producer.send(nextMessage(producerSession, 5));
        producer.setPriority(1);
        producer.send(nextMessage(producerSession, 6));
        // Out of order BCA
        producer.setPriority(4);
        producer.send(nextMessage(producerSession, 7));
        producer.setPriority(1);
        producer.send(nextMessage(producerSession, 8));
        producer.setPriority(9);
        producer.send(nextMessage(producerSession, 9));
        // Reverse order CBA
        producer.setPriority(1);
        producer.send(nextMessage(producerSession, 10));
        producer.setPriority(4);
        producer.send(nextMessage(producerSession, 11));
        producer.setPriority(9);
        producer.send(nextMessage(producerSession, 12));
