    }
}

@Test
public void testSendForeignMessage() throws Exception {
    final Destination replyTo = createQueue(getTestName() + "_replyTo");
    final Queue queue = createQueue(getTestName());
    final Connection connection = getConnection();
    try {
        final Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        final String jmsType = "TestJmsType";
        final String correlationId = "testCorrelationId";
        final ObjectMessage message = session.createObjectMessage();
        final ObjectMessage foreignMessage = Reflection.newProxy(ObjectMessage.class, new AbstractInvocationHandler() {

            @Override
            protected Object handleInvocation(final Object proxy, final Method method, final Object[] args) throws Throwable {
                return method.invoke(message, args);
            }
        });
        foreignMessage.setJMSCorrelationID(correlationId);
        foreignMessage.setJMSType(jmsType);
        foreignMessage.setJMSReplyTo(replyTo);
        Serializable payload = UUID.randomUUID();
        foreignMessage.setObject(payload);
        final MessageConsumer consumer = session.createConsumer(queue);
        final MessageProducer producer = session.createProducer(queue);
        producer.send(foreignMessage);
        connection.start();
        Message receivedMessage = consumer.receive(getReceiveTimeout());
        assertTrue(receivedMessage instanceof ObjectMessage, "ObjectMessage was not received ");
        assertEquals(foreignMessage.getJMSCorrelationID(), receivedMessage.getJMSCorrelationID(), "JMSCorrelationID mismatch");
        assertEquals(foreignMessage.getJMSType(), receivedMessage.getJMSType(), "JMSType mismatch");
        assertEquals(foreignMessage.getJMSReplyTo(), receivedMessage.getJMSReplyTo(), "JMSReply To mismatch");
        assertEquals(foreignMessage.getJMSMessageID(), receivedMessage.getJMSMessageID(), "JMSMessageID mismatch");
        assertEquals(Message.DEFAULT_PRIORITY, receivedMessage.getJMSPriority(), "JMS Default priority should be default");
        assertEquals(payload, ((ObjectMessage) receivedMessage).getObject(), "Message payload not as expected");
    } finally {
        connection.close();
    }
}

